import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Month 2021: Ceph in Research & Scientific Computing BoF","description":"","frontmatter":{"title":"Ceph Month 2021: Ceph in Research & Scientific Computing BoF","date":"2021-06-10T00:00:00.000Z","updated":"2021-06-11T00:00:00.000Z","tags":["Ceph","分布式存储","科学计算","RBD镜像","CephFS快照","Ceph升级"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Ceph_in_Research_Scientific_Computing_BoF.md","filePath":"posts/2021/Ceph_Month_2021_-_Ceph_in_Research_Scientific_Computing_BoF.md","lastUpdated":1780459816000}'),h={name:"posts/2021/Ceph_Month_2021_-_Ceph_in_Research_Scientific_Computing_BoF.md"};function l(n,e,r,p,s,_){return t(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议是关于Ceph分布式存储系统和科学计算的“鸟类聚会”，由Kevin主持。会议每两个月举行一次，旨在讨论Ceph和科学计算相关的话题，包括有趣的用例、实验和技术挑战。</p><h4 id="主要讨论议题" tabindex="-1">主要讨论议题 <a class="header-anchor" href="#主要讨论议题" aria-label="Permalink to &quot;主要讨论议题&quot;">​</a></h4><ol><li><strong>Ceph RBD Mirroring</strong>: 会上将有一位新成员进行关于RBD镜像的演示。</li><li><strong>CephFS Snapshots</strong>: CERN团队在测试CephFS的快照功能时，发现Nautilus和Octopus版本中快照删除操作非常慢，建议升级到Pacific版本解决。</li><li><strong>Ceph Adm的使用</strong>: 讨论了Ceph Adm在管理Ceph集群中的应用，特别是与Puppet的集成问题和容器镜像的管理。</li><li><strong>Ceph升级经验分享</strong>: 分享了从Luminous升级到Octopus的经验，强调了升级过程中的关键步骤和注意事项。</li><li><strong>CephFS性能问题</strong>: 讨论了CephFS在处理大量文件时的性能问题，特别是MDS日志段的管理和清理。</li><li><strong>Ceph版本和包管理</strong>: 讨论了Ceph版本的升级策略和包管理的最佳实践，包括从FileStore迁移到BlueStore的计划。</li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>建议升级到Ceph Pacific版本以解决快照管理的性能问题。</li><li>需要进一步测试和验证Ceph Adm在不同环境下的兼容性和功能。</li><li>强调了在升级Ceph集群时，特别是涉及安全特性的升级时，需要特别注意文档中的警告和建议操作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续测试Ceph Adm的功能和性能，特别是在集成Puppet和容器镜像管理方面。</li><li>计划在下一个会议周期再次举行“鸟类聚会”，以继续讨论Ceph和科学计算的相关话题。</li><li>对于CephFS的性能问题，将继续进行压力测试和优化，以确保在大规模文件系统中的稳定性和性能。</li></ul><h4 id="其他注意事项" tabindex="-1">其他注意事项 <a class="header-anchor" href="#其他注意事项" aria-label="Permalink to &quot;其他注意事项&quot;">​</a></h4><ul><li>会议中提到的关于Ceph Adm和Podman的特定问题，需要进一步的技术验证和社区反馈。</li><li>对于Ceph版本的升级，特别是从FileStore到BlueStore的迁移，需要详细的计划和测试，以确保数据的安全和服务的连续性。</li></ul><p>本次会议为Ceph社区成员提供了一个交流和分享经验的平台，有助于推动Ceph在科学计算领域的应用和发展。</p>',12)])])}const d=i(h,[["render",l]]);export{C as __pageData,d as default};
